401	function useQuery_<TData, TVariables extends OperationVariables>(
402	  query: DocumentNode | TypedDocumentNode<TData, TVariables>,
403	  options:
404	    | SkipToken
405	    | useQuery.Options<
406	        NoInfer<TData>,
407	        NoInfer<TVariables>
408	      > = {} as useQuery.Options<TData, TVariables>
409	): useQuery.Result<TData, TVariables> {
410	  const client = useApolloClient(
411	    typeof options === "object" ? options.client : undefined
412	  );
413	  const { ssr } = typeof options === "object" ? options : {};
414	
415	  const watchQueryOptions = useOptions(
416	    query,
417	    options,
418	    client.defaultOptions.watchQuery
419	  );
420	
421	  function createState(
422	    previous?: InternalState<TData, TVariables>
423	  ): InternalState<TData, TVariables> {
424	    const observable = client.watchQuery(watchQueryOptions);
425	
426	    return {
427	      client,
428	      query,
429	      observable,
430	      resultData: {
431	        current: observable.getCurrentResult(),
432	        // Reuse previousData from previous InternalState (if any) to provide
433	        // continuity of previousData even if/when the query or client changes.
434	        previousData: previous?.resultData.current.data as TData,
435	        variables: observable.variables,
436	      },
437	    };
438	  }
439	
440	  let [state, setState] = React.useState(createState);
441	
442	  if (client !== state.client || query !== state.query) {
443	    // If the client or query have changed, we need to create a new InternalState.
444	    // This will trigger a re-render with the new state, but it will also continue
445	    // to run the current render function to completion.
446	    // Since we sometimes trigger some side-effects in the render function, we
447	    // re-assign `state` to the new state to ensure that those side-effects are
448	    // triggered with the new state.
449	    setState((state = createState(state)));
450	  }
451	
452	  const { observable, resultData } = state;
453	
454	  useInitialFetchPolicyIfNecessary<TData, TVariables>(
455	    watchQueryOptions,
456	    observable
457	  );
458	
459	  useResubscribeIfNecessary<TData, TVariables>(
460	    resultData, // might get mutated during render
461	    observable, // might get mutated during render
462	    watchQueryOptions
463	  );
464	
465	  const result = useResult<TData, TVariables>(observable, resultData, ssr);
466	
467	  const obsQueryFields = React.useMemo(
468	    () => ({
469	      refetch: observable.refetch.bind(observable),
470	      fetchMore: observable.fetchMore.bind(observable),
471	      updateQuery: observable.updateQuery.bind(observable),
472	      startPolling: observable.startPolling.bind(observable),
473	      stopPolling: observable.stopPolling.bind(observable),
474	      subscribeToMore: observable.subscribeToMore.bind(observable),
475	    }),
476	    [observable]
477	  );
478	
479	  const previousData = resultData.previousData;
480	  return React.useMemo(() => {
481	    const { partial, ...rest } = result;
482	
483	    return {
484	      ...rest,
485	      client,
486	      observable,
487	      variables: observable.variables,
488	      previousData,
489	      ...obsQueryFields,
490	    };
491	  }, [result, client, observable, previousData, obsQueryFields]);
492	}
