494	const fromSkipToken = Symbol();
495	
496	function useOptions<TData, TVariables extends OperationVariables>(
497	  query: DocumentNode | TypedDocumentNode<TData, TVariables>,
498	  options: SkipToken | useQuery.Options<NoInfer<TData>, NoInfer<TVariables>>,
499	  defaultOptions: Partial<ApolloClient.WatchQueryOptions<any, any>> | undefined
500	): ApolloClient.WatchQueryOptions<TData, TVariables> {
501	  return useDeepMemo<ApolloClient.WatchQueryOptions<TData, TVariables>>(() => {
502	    if (options === skipToken) {
503	      const opts: ApolloClient.WatchQueryOptions<TData, TVariables> = {
504	        ...mergeOptions(defaultOptions as any, {
505	          query,
506	          fetchPolicy: "standby",
507	        }),
508	        [variablesUnknownSymbol]: true,
509	      };
510	      (opts as any)[fromSkipToken] = true;
511	
512	      return opts;
513	    }
514	
515	    const watchQueryOptions: ApolloClient.WatchQueryOptions<TData, TVariables> =
516	      mergeOptions(defaultOptions as any, { ...options, query });
517	
518	    if (options.skip) {
519	      watchQueryOptions.initialFetchPolicy =
520	        options.initialFetchPolicy || options.fetchPolicy;
521	      watchQueryOptions.fetchPolicy = "standby";
522	    }
523	
524	    return watchQueryOptions;
525	  }, [query, options, defaultOptions]);
526	}
