528	function useInitialFetchPolicyIfNecessary<
529	  TData,
530	  TVariables extends OperationVariables,
531	>(
532	  watchQueryOptions: ApolloClient.WatchQueryOptions<TData, TVariables>,
533	  observable: ObsQueryWithMeta<TData, TVariables>
534	) {
535	  "use no memo";
536	  if (!watchQueryOptions.fetchPolicy) {
537	    watchQueryOptions.fetchPolicy = observable.options.initialFetchPolicy;
538	  }
539	}
