apollo/client/testing/internal\";\nimport { MockedProvider } from \"@apollo/client/testing/react\";\nimport type { DeepPartial, Reference } from \"@apollo/client/utilities\";\nimport { concatPagination } from \"@apollo/client/utilities\";\nimport { InvariantError } from \"@apollo/client/utilities/invariant\";\n\nconst IS_REACT_17 = React.version.startsWith(\"17\");\nconst IS_REACT_18 = React.version.startsWith(\"18\");\n\ndescribe(\"useQuery Hook\", () => {\n  describe(\"General use\", () => {\n    it(\"should handle a simple query\", async () => {\n      const query = gql`\n        {\n          hello\n        }\n      `;\n      const mocks = [\n        {\n          request: { query },\n          result: { data: { hello: \"world\" } },\n        },\n      ];\n\n      const wrapper = ({ children }: any) => (\n        <MockedProvider mocks={mocks}>{children}</MockedProvider>\n      );\n\n      using _disabledAct = disableActEnvironment();\n      const { takeSnapshot } = await renderHookToSnapshotStream(\n        () => useQuery(query),\n        { wrapper }\n      );\n\n      {\n        const result = await takeSnapshot();\n\n        expect(result).toStrictEqualTyped({\n          data: undefined,\n          dataState: \"empty\",\n          loading: true,\n          networkStatus: NetworkStatus.loading,\n          previousData: undefined,\n          variables: {},\n        });\n      }\n\n      {\n        const result = await takeSnapshot();\n\n        expect(result).toStrictEqualTyped({\n          data: { hello: \"world\" },\n          dataState: \"complete\",\n          loading: false,\n          networkStatus: NetworkStatus.ready,\n          previousData: undefined,\n          variables: {},\n        });\n      }\n\n      await expect(takeSnapshot).not.toRerender();\n    });\n\n    it(\"useQuery result is referentially stable\", async () => {\n      const query = gql`\n        {\n          hello\n        }\n      `;\n      const mocks = [\n        {\n          request: { query },\n          result: { data: { hello: \"world\" } },\n        },\n      ];\n      const wrapper = ({ children }: any) => (\n        <MockedProvider mocks={mocks}>{children}</MockedProvider>\n      );\n\n      using _disabledAct = disableActEnvironment();\n      const { takeSnapshot, rerender } = await renderHookToSnapshotStream(\n        () => useQuery(query),\n        {\n          wrapper,\n        }\n      );\n\n      {\n        const result = await takeSnapshot();\n\n        expect(result).toStrictEqualTyped({\n          data: undefined,\n          dataState: \"empty\",\n          loading: true,\n          networkStatus: NetworkStatus.loading,\n          previousData: undefined,\n          variables: {},\n        });\n      }\n\n      let oldResult: useQuery.Result<any, OperationVariables>;\n\n      {\n        const result = (oldResult = await takeSnapshot());\n\n        expect(result).toStrictEqualTyped({\n          data: { hello: \"world\" },\n          dataState: \"complete\",\n          loading: false,\n          networkStatus: NetworkStatus.ready,\n          previousData: undefined,\n          variables: {},\n        });\n      }\n\n      await rerender();\n\n      {\n        const result = await takeSnapshot();\n\n        expect(result).toStrictEqualTyped({\n          data: { hello: \"world\" },\n          dataState: \"complete\",\n          loading: false,\n          networkStatus: NetworkStatus.ready,\n          previousData: undefined,\n          variables: {},\n        });\n\n        expect(result).toBe(oldResult);\n      }\n\n      await expect(takeSnapshot).not.toRerender();\n    });\n\n    it(\"useQuery produces the expected renders initially\", async () => {\n      const query = gql`\n        {\n          hello\n        }\n      `;\n      const mocks = [\n        {\n          request: { query },\n          result: { data: { hello: \"world\" } },\n        },\n      ];\n      const wrapper = ({ children }: any) => (\n        <MockedProvider mocks={mocks}>{children}</MockedProvider>\n      );\n\n      using _disabledAct = disableActEnvironment();\n      const { takeSnapshot, rerender } = await renderHookToSnapshotStream(\n        () => useQuery(query),\n        {\n          wrapper,\n        }\n      );\n\n      {\n        const result = await takeSnapshot();\n\n        expect(result).toStrictEqualTyped({\n          data: undefined,\n          dataState: \"empty\",\n          loading: true,\n          networkStatus: NetworkStatus.loading,\n          previousData: undefined,\n          variables: {},\n        });\n      }\n\n      {\n        const result = await takeSnapshot();\n\n        expect(result).toStrictEqualTyped({\n          data: { hello: \"world\" },\n          dataState: \"complete\",\n          loading: false,\n          networkStatus: NetworkStatus.ready,\n          previousData: undefined,\n          variables: {},\n        });\n      }\n\n      await rerender();\n\n      {\n        const result = await takeSnapshot();\n\n        expect(result).toStrictEqualTyped({\n          data: { hello: \"world\" },\n          dataState: \"complete\",\n          loading: false,\n          networkStatus: NetworkStatus.ready,\n          previousData: undefined,\n          variables: {},\n        });\n      }\n\n      await expect(takeSnapshot).not.toRerender();\n    });\n\n    it(\"useQuery produces the expected frames when variables change\", async () => {\n      const query = gql`\n        query ($id: Int) {\n          hello(id: $id)\n        }\n      `;\n      const mocks = [\n        {\n          request: { query, variables: { id: 1 } },\n          result: { data: { hello: \"world 1\" } },\n        },\n        {\n          request: { query, variables: { id: 2 } },\n          result: { data: { hello: \"world 2\" } },\n        },\n      ];\n      const wrapper = ({ children }: any) => (\n        <MockedProvider mocks={mocks}>{children}</MockedProvider>\n      );\n\n      using _disabledAct = disableAc