             case \"B\":\n                  setTimeout(() => {\n                    observer.next({ data: bData });\n                    observer.complete();\n                  }, 10);\n                  break;\n              }\n            })\n        ),\n      });\n    }\n\n    async function check(\n      aFetchPolicy: WatchQueryFetchPolicy,\n      bFetchPolicy: WatchQueryFetchPolicy\n    ) {\n      const client = makeClient();\n      const { result } = renderHook(\n        () => ({\n          a: useQuery(aQuery, { fetchPolicy: aFetchPolicy }),\n          b: useQuery(bQuery, { fetchPolicy: bFetchPolicy }),\n        }),\n        {\n          wrapper: ({ children }) => (\n            <ApolloProvider client={client}>{children}</ApolloProvider>\n          ),\n        }\n      );\n\n      expect(result.current.a).toStrictEqualTyped({\n        data: undefined,\n        dataState: \"empty\",\n        loading: true,\n        networkStatus: NetworkStatus.loading,\n        previousData: undefined,\n        variables: {},\n      });\n      expect(result.current.b).toStrictEqualTyped({\n        data: undefined,\n        dataState: \"empty\",\n        loading: true,\n        networkStatus: NetworkStatus.loading,\n        previousData: undefined,\n        variables: {},\n      });\n\n      await waitFor(() => {\n        expect(result.current.a.loading).toBe(false);\n        expect(result.current.b.loading).toBe(false);\n      });\n\n      expect(result.current.a).toStrictEqualTyped({\n        data: aData,\n        dataState: \"complete\",\n        loading: false,\n        networkStatus: NetworkStatus.ready,\n        previousData: undefined,\n        variables: {},\n      });\n      expect(result.current.b).toStrictEqualTyped({\n        data: bData,\n        dataState: \"complete\",\n        loading: false,\n        networkStatus: NetworkStatus.ready,\n        previousData: undefined,\n        variables: {},\n      });\n    }\n\n    // TODO: Eventually move the \"check\" code back into these test so we can\n    // check them render-by-render with renderHookToSnapshotStream\n    it(\"cache-first for both\", () => check(\"cache-first\", \"cache-first\"));\n\n    it(\"cache-first first, cache-and-network second\", () =>\n      check(\"cache-first\", \"cache-and-network\"));\n\n    it(\"cache-first first, network-only second\", () =>\n      check(\"cache-first\", \"network-only\"));\n\n    it(\"cache-and-network for both\", () =>\n      check(\"cache-and-network\", \"cache-and-network\"));\n\n    it(\"cache-and-network first, cache-first second\", () =>\n      check(\"cache-and-network\", \"cache-first\"));\n\n    it(\"cache-and-network first, network-only second\", () =>\n      check(\"cache-and-network\", \"network-only\"));\n\n    it(\"network-only for both\", () => check(\"network-only\", \"network-only\"));\n\n    it(\"network-only first, cache-first second\", () =>\n      check(\"network-only\", \"cache-first\"));\n\n    it(\"network-only first, cache-and-network second\", () =>\n      check(\"network-only\", \"cache-and-network\"));\n  });\n\n  describe(\"regression test issue #9204\", () => {\n    // TODO: See if we can rewrite this with renderHookToSnapshotStream and\n    // check output of hook to ensure its a stable object\n    it(\"should handle a simple query\", async () => {\n      const query: TypedDocumentNode<\n        { hello: string },\n        Record<string, never>\n      > = gql`\n        {\n          hello\n        }\n      `;\n      const mocks = [\n        {\n          request: { query },\n          result: { data: { hello: \"world\" } },\n        },\n      ];\n\n      const Component = ({\n        query,\n      }: {\n        query: TypedDocumentNode<{ hello: string }, Record<string, never>>;\n      }) => {\n        const [counter, setCounter] = useState(0);\n        const result = useQuery(query);\n\n        useEffect(() => {\n          /**\n           * IF the return value from useQuery changes on each render,\n           * this component will re-render in an infinite loop.\n           */\n          if (counter > 10) {\n            console.error(`Too many results (${counter})`);\n          } else {\n            setCounter((c) => c + 1);\n          }\n        }, [result, result.data]);\n\n        if (result.loading) return null;\n\n        return (\n          <div>\n            {result.data!.hello}\n            {counter}\n          </div>\n        );\n      };\n\n      render(\n        <MockedProvider mocks={mocks}>\n          <Component query={query} />\n        </MockedProvider>\n      );\n\n      await waitFor(() => {\n        expect(screen.getByText(\"world2\")).toBeTruthy();\n      });\n    });\n  });\n\n  // https://github.com/apollographql/apollo-client/issues/10222\n  describe(\"regression test issue #10222\", () => {\n    it(\"maintains initial fetch policy when component unmounts and remounts\", async () => {\n      let helloCount = 1;\n      const query = gql`\n        {\n          hello\n        }\n      `;\n      const link = new ApolloLink(() => {\n        return new Observable((observer) => {\n          const timer = setTimeout(() => {\n            observer.next({ data: { hello: `hello ${helloCount++}` } });\n            observer.complete();\n          }, 50);\n\n          return () => {\n            clearTimeout(timer);\n          };\n        });\n      });\n\n      const cache = new InMemoryCache();\n\n      const client = new ApolloClient({\n        link,\n        cache,\n      });\n\n      let setShow: Function;\n      const Toggler = ({ children }: { children: ReactNode }) => {\n        const [show, _setShow] = useState(true);\n        setShow = _setShow;\n\n        return show ? <>{children}</> : null;\n      };\n\n      const { result } = renderHook(\n        () =>\n          useQuery(query, {\n            fetchPolicy: \"network-only\",\n            nextFetchPolicy: \"cache-first\",\n          }),\n        {\n          wrapper: ({ children }) => (\n            <ApolloProvider client={client}>\n              <Toggler>{children}</Toggler>\n            </ApolloProvider>\n          ),\n        }\n      );\n\n      expect(result.current).toStrictEqualTyped({\n        data: undefined,\n        dataState: \"empty\",\n        loading: true,\n        networkStatus: NetworkStatus.loading,\n        previousData: undefined,\n        variables: {},\n      });\n\n      await waitFor(() => {\n        expect(result.current.loading).toBe(false);\n      });\n\n      expect(result.current).toStrictEqualTyped({\n        data: { hello: \"hello 1\" },\n        dataState: \"complete\",\n        loading: false,\n        networkStatus: NetworkStatus.ready,\n        previousData: undefined,\n        variables: {},\n      });\n\n      expect(cache.readQuery({ query })).toEqual({ hello: \"hello 1\" });\n\n      act(() => {\n        setShow(false);\n      });\n\n      act(() => {\n        setShow(true);\n      });\n\n      expect(result.current).toStrictEqualTyped({\n        data: undefined,\n        dataState: \"empty\",\n        loading: true,\n        networkStatus: NetworkStatus.loading,\n        previousData: undefined,\n        variables: {},\n      });\n\n      await waitFor(() => {\n        expect(result.current.loading).toBe(false);\n      });\n\n      expect(result.current).toStrictEqualTyped({\n        data: { hello: \"hello 2\" },\n        dataState: \"complete\",\n        loading: false,\n        networkStatus: NetworkStatus.ready,\n        previousData: undefined,\n        variables: {},\n      });\n\n      expect(cache.readQuery({ query })).toEqual({ hello: \"hello 2\" });\n    });\n  });\n\n  describe(\"interaction with `prioritizeCacheValues`\", () => {\n    const cacheData = { something: \"foo\" };\n    const networkData = { something: \"bar\" };\n    type TestQueryValue = typeof cacheData;\n\n    test.each<{\n      fetchPolicy: WatchQueryFetchPolicy;\n      populateCache: boolean;\n      expectedSnapshots: Array<\n        Pick<\n          useQuery.Result<\n            TestQueryValue,\n            OperationVariables,\n            \"empty\" | \"complete\" | \"streaming\"\n          >,\n          | \"loading\"\n          | \"data\"\n          | \"networkStatus\"\n          | \"dataState\"\n          | \"error\"\n          | \"previousData\"\n          | \"variables\"\n        >\n      >;\n      expectedFetchCount: number;\n    }>([\n      // cache-first is the default behavior with `prioritizeCacheValues`\n      {\n        fetchPolicy: \"cache-first\",\n        populateCache: false,\n        expectedSnapshots: [\n          {\n            loading: true,\n            data: undefined,\n            networkStatus: NetworkStatus.loading,\n            dataState: \"empty\" as const,\n            previousData: undefined,\n            variables: {},\n          },\n          {\n            loading: false,\n            data: networkData,\n            networkStatus: NetworkStatus.ready,\n            dataState: \"complete\" as const,\n            previousData: undefined,\n            variables: {},\n          },\n        ],\n        expectedFetchCount: 1,\n      },\n      {\n        fetchPolicy: \"cache-first\",\n        populateCache: true,\n        expectedSnapshots: [\n          {\n            loading: false,\n            data: cacheData,\n            networkStatus: NetworkStatus.ready,\n            dataState: \"complete\" as const,\n            previousData: undefined,\n            variables: {},\n          },\n        ],\n        expectedFetchCount: 0,\n      },\n      // cache-only should never cause network requests\n      {\n        fetchPolicy: \"cache-only\",\n        populateCache: false,\n        expectedSnapshots: [\n          {\n            loading: false,\n            data: undefined,\n            networkStatus: NetworkStatus.ready,\n            dataState: \"empty\" as const,\n            previousData: undefined,\n            variables: {},\n          },\n        ],\n        expectedFetchCount: 0,\n      },\n      {\n        fetchPolicy: \"cache-only\",\n        populateCache: true,\n        expectedSnapshots: [\n          {\n            loading: false,\n            data: cacheData,\n            networkStatus: NetworkStatus.ready,\n            dataState: \"complete\" as const,\n            previousData: undefined,\n            variables: {},\n          },\n        ],\n        expectedFetchCount: 0,\n      },\n      // cache-and-network should avoid fetching if cache is populated\n      {\n        fetchPolicy: \"cache-and-network\",\n        populateCache: false,\n        expectedSnapshots: [\n          {\n            loading: true,\n            data: undefined,\n            networkStatus: NetworkStatus.loading,\n            dataState: \"empty\" as const,\n            previousData: undefined,\n            variables: {},\n          },\n          {\n            loading: false,\n            data: networkData,\n            networkStatus: NetworkStatus.ready,\n            dataState: \"complete\" as const,\n            previousData: undefined,\n            variables: {},\n          },\n        ],\n        expectedFetchCount: 1,\n      },\n      {\n        fetchPolicy: \"cache-and-network\",\n        populateCache: true,\n        expectedSnapshots: [\n          {\n            loading: false,\n            data: cacheData,\n            networkStatus: NetworkStatus.ready,\n            dataState: \"complete\" as const,\n            previousData: undefined,\n            variables: {},\n          },\n        ],\n        expectedFetchCount: 0,\n      },\n      // `network-only` should return a loading result and make a network request\n      // if values are missing from cache, but if cache values are present,\n      // during `prioritizeCacheValues` it is actually allowed to immediately\n      // read from the cache and avoid a network request\n      {\n        fetchPolicy: \"network-only\",\n        populateCache: false,\n        expectedSnapshots: [\n          {\n            loading: true,\n            data: undefined,\n            networkStatus: NetworkStatus.loading,\n            dataState: \"empty\" as const,\n            previousData: undefined,\n            variables: {},\n          },\n          {\n            loading: false,\n            data: networkData,\n            networkStatus: NetworkStatus.ready,\n            dataState: \"complete\" as const,\n            previousData: undefined,\n            variables: {},\n          },\n        ],\n        expectedFetchCount: 1,\n      },\n      {\n        fetchPolicy: \"network-only\",\n        populateCache: true,\n        expectedSnapshots: [\n          {\n            loading: false,\n            data: cacheData,\n            networkStatus: NetworkStatus.ready,\n            dataState: \"complete\" as const,\n            previousData: undefined,\n            variables: {},\n          },\n        ],\n        expectedFetchCount: 0,\n      },\n      // no-cache should always fetch and never read from the cache\n      {\n        fetchPolicy: \"no-cache\",\n        populateCache: false,\n        expectedSnapshots: [\n          {\n            loading: true,\n            data: undefined,\n            networkStatus: NetworkStatus.loading,\n            dataState: \"empty\" as const,\n            previousData: undefined,\n            variables: {},\n          },\n          {\n            loading: false,\n            data: networkData,\n            networkStatus: NetworkStatus.ready,\n            dataState: \"complete\" as const,\n            previousData: undefined,\n            variables: {},\n          },\n        ],\n        expectedFetchCount: 1,\n      },\n      {\n        fetchPolicy: \"no-cache\",\n        populateCache: true,\n        expectedSnapshots: [\n          {\n            loading: true,\n            data: undefined,\n            networkStatus: NetworkStatus.loading,\n            dataState: \"empty\" as const,\n            previousData: undefined,\n            variables: {},\n          },\n          {\n            loading: false,\n            data: networkData,\n            networkStatus: NetworkStatus.ready,\n            dataState: \"complete\" as const,\n            previousData: undefined,\n            variables: {},\n          },\n        ],\n        expectedFetchCount: 1,\n      },\n      // `standby` should never show a loading state or cause network requests\n      {\n        fetchPolicy: \"standby\",\n        populateCache: false,\n        expectedSnapshots: [\n          {\n            loading: false,\n            data: undefined,\n            networkStatus: NetworkStatus.ready,\n            dataState: \"empty\" as const,\n            previousData: undefined,\n            variables: {},\n          },\n        ],\n        expectedFetchCount: 0,\n      },\n      {\n        fetchPolicy: \"standby\",\n        populateCache: true,\n        expectedSnapshots: [\n          {\n            loading: false,\n            data: undefined,\n            networkStatus: NetworkStatus.ready,\n            dataState: \"empty\" as const,\n            previousData: undefined,\n            variables: {},\n          },\n        ],\n        expectedFetchCount: 0,\n      },\n    ])(\n      \"fetchPolicy: '$fetchPolicy' with prioritizeCacheValues (cache populated: $populateCache)\",\n      async ({\n        fetchPolicy,\n        populateCache,\n        expectedSnapshots,\n        expectedFetchCount,\n      }) => {\n        using _disabledAct = disableActEnvironment();\n\n        const query: TypedDocumentNode<TestQueryValue> = gql`\n          query {\n            something\n          }\n        `;\n\n        const link = new MockLink([\n          { request: { query }, result: { data: networkData } },\n        ]);\n        const linkSpy = jest.spyOn(link, \"request\");\n\n        const client = new ApolloClient({\n          cache: new InMemoryCache(),\n          link,\n        });\n\n        if (populateCache) {\n          client.writeQuery({ query, data: cacheData });\n        }\n\n        client.prioritizeCacheValues = true;\n\n        const { takeSnapshot } = await renderHookToSnapshotStream(\n          () => useQuery(query, { fetchPolicy }),\n          {\n            wrapper: ({ children }) => (\n              <ApolloProvider client={client}>{children}</ApolloProvider>\n            ),\n          }\n        );\n\n        for (const expected of expectedSnapshots) {\n          await expect(takeSnapshot()).resolves.toStrictEqualTyped(\n            expected as useQuery.Result<\n              TestQueryValue,\n              OperationVariables,\n              \"empty\" | \"complete\" | \"streaming\"\n            >\n          );\n        }\n\n        await expect(takeSnapshot).not.toRerender();\n        expect(linkSpy).toHaveBeenCalledTimes(expectedFetchCount);\n      }\n    );\n  });\n\n  test(\"calling `clearStore` while a query is running puts the hook into an error state\", async () => {\n    const query = gql`\n      query {\n        hello\n      }\n    `;\n\n    const link = new MockSubscriptionLink();\n    let requests = 0;\n    link.onSetup(() => requests++);\n    const client = new ApolloClient({\n      link,\n      cache: new InMemoryCache(),\n    });\n    using _disabledAct = disableActEnvironment();\n    const { takeSnapshot } = await renderHookToSnapshotStream(\n      () => useQuery(query),\n      {\n        wrapper: ({ children }) => (\n          <ApolloProvider client={client}>{children}</ApolloProvider>\n        ),\n      }\n    );\n\n    await wait(10);\n    expect(requests).toBe(1);\n\n    await expect(takeSnapshot()).resolves.toStrictEqualTyped({\n      data: undefined,\n      dataState: \"empty\",\n      loading: true,\n      networkStatus: NetworkStatus.loading,\n      previousData: undefined,\n      variables: {},\n    });\n\n    await client.clearStore();\n\n    await expect(takeSnapshot()).resolves.toStrictEqualTyped({\n      data: undefined,\n      dataState: \"empty\",\n      error: new InvariantError(\n        \"Store reset while query was in flight (not completed in link chain)\"\n      ),\n      loading: false,\n      networkStatus: NetworkStatus.error,\n      previousData: undefined,\n      variables: {},\n    });\n\n    link.simulateResult({ result: { data: { hello: \"Greetings\" } } }, true);\n    await expect(takeSnapshot).not.toRerender({ timeout: 50 });\n    expect(requests).toBe(1);\n  });\n\n  // https://github.com/apollographql/apollo-client/issues/11938\n  it(\"does not emit `data` on previous fetch when a 2nd fetch is kicked off and the result returns an error when errorPolicy is none\", async () => {\n    const query = gql`\n      query {\n        user {\n          id\n          name\n        }\n      }\n    `;\n\n    const graphQLError: GraphQLFormattedError = { message: \"Cannot get name\" };\n\n    const mocks = [\n      {\n        request: { query },\n        result: {\n          data: { user: { __typename: \"User\", id: \"1\", name: null } },\n          errors: [graphQLError],\n        },\n        delay: 10,\n        maxUsageCount: Number.POSITIVE_INFINITY,\n      },\n    ];\n\n    using _disabledAct = disableActEnvironment();\n    const { takeSnapshot, getCurrentSnapshot } =\n      await renderHookToSnapshotStream(() => useQuery(query), {\n        wrapper: ({ children }) => (\n          <MockedProvider mocks={mocks}>{children}</MockedProvider>\n        ),\n      });\n\n    await expect(takeSnapshot()).resolves.toStrictEqualTyped({\n      data: undefined,\n      dataState: \"empty\",\n      loading: true,\n      networkStatus: NetworkStatus.loading,\n      previousData: undefined,\n      variables: {},\n    });\n\n    await expect(takeSnapshot()).resolves.toStrictEqualTyped({\n      data: undefined,\n      dataState: \"empty\",\n      error: new CombinedGraphQLErrors({\n        data: { user: { __typename: \"User\", id: \"1\", name: null } },\n        errors: [graphQLError],\n      }),\n      loading: false,\n      networkStatus: NetworkStatus.error,\n      previousData: undefined,\n      variables: {},\n    });\n\n    const { refetch } = getCurrentSnapshot();\n\n    refetch().catch(() => {});\n    refetch().catch(() => {});\n\n    await expect(takeSnapshot()).resolves.toStrictEqualTyped({\n      data: undefined,\n      dataState: \"empty\",\n      loading: true,\n      networkStatus: NetworkStatus.refetch,\n      previousData: undefined,\n      variables: {},\n    });\n\n    if (IS_REACT_17) {\n      await expect(takeSnapshot()).resolves.toStrictEqualTyped({\n        data: undefined,\n        dataState: \"empty\",\n        error: new CombinedGraphQLErrors({\n          data: { user: { __typename: \"User\", id: \"1\", name: null } },\n          errors: [graphQLError],\n        }),\n        loading: true,\n        networkStatus: NetworkStatus.refetch,\n        previousData: undefined,\n        variables: {},\n      });\n    }\n\n    await expect(takeSnapshot()).resolves.toStrictEqualTyped({\n      data: undefined,\n      dataState: \"empty\",\n      error: new CombinedGraphQLErrors({\n        data: { user: { __typename: \"User\", id: \"1\", name: null } },\n        errors: [graphQLError],\n      }),\n      loading: false,\n      networkStatus: NetworkStatus.error,\n      previousData: undefined,\n      variables: {},\n    });\n\n    await expect(takeSnapshot).not.toRerender({ timeout: 200 });\n  });\n\n  test(\"initializes with loading: false on an empty cache when using `cache-only`\", async () => {\n    const query = gql`\n      query {\n        hello\n      }\n    `;\n    const client = new ApolloClient({\n      cache: new InMemoryCache(),\n      link: ApolloLink.empty(),\n    });\n\n    using _disabledAct = disableActEnvironment();\n    const { takeSnapshot } = await renderHookToSnapshotStream(\n      () => useQuery(query, { fetchPolicy: \"cache-only\" }),\n      {\n        wrapper: ({ children }) => (\n          <ApolloProvider client={client}>{children}</ApolloProvider>\n        ),\n  