gmentRefs\"?: { UserFieldsFragment: UserFieldsFragment } };\n      }\n\n      const query: TypedDocumentNode<Query, Record<string, never>> = gql`\n        query MaskedQuery {\n          currentUser {\n            id\n            name\n            ...UserFields\n          }\n        }\n\n        fragment UserFields on User {\n          age\n        }\n      `;\n\n      const mocks = [\n        {\n          request: { query },\n          result: {\n            data: {\n              currentUser: {\n                __typename: \"User\",\n                id: 1,\n                name: \"Test User\",\n                age: 30,\n              },\n            },\n          },\n        },\n      ];\n\n      const client = new ApolloClient({\n        dataMasking: true,\n        cache: new InMemoryCache(),\n        link: new MockLink(mocks),\n      });\n\n      const renderStream =\n        createRenderStream<useQuery.Result<Query, Record<string, never>>>();\n\n      function App() {\n        const result = useQuery(query);\n\n        renderStream.replaceSnapshot(result);\n\n        return null;\n      }\n\n      using _disabledAct = disableActEnvironment();\n      await renderStream.render(<App />, {\n        wrapper: ({ children }) => (\n          <ApolloProvider client={client}>{children}</ApolloProvider>\n        ),\n      });\n\n      {\n        const { snapshot } = await renderStream.takeRender();\n\n        expect(snapshot).toStrictEqualTyped({\n          data: undefined,\n          dataState: \"empty\",\n          loading: true,\n          networkStatus: NetworkStatus.loading,\n          previousData: undefined,\n          variables: {},\n        });\n      }\n\n      {\n        const { snapshot } = await renderStream.takeRender();\n\n        expect(snapshot).toStrictEqualTyped({\n          data: {\n            currentUser: {\n              __typename: \"User\",\n              id: 1,\n              name: \"Test User\",\n            },\n          },\n          dataState: